def _markup(self, entry):
        """
        Recursively generates HTML for the current entry.

        Parameters
        ----------
        entry : object
            Object to convert to HTML. Maybe be a single entity or contain multiple and/or nested objects.

        Returns
        -------
        str
            String of HTML formatted json.
        """
        if isinstance(entry, list):
            return ''.join([self._markup(e) for e in entry])

        if isinstance(entry, dict):
            return self._markup_dict(entry)

        if isinstance(entry, str):
            return self._markup_str(entry)

        if isinstance(entry, int) or isinstance(entry, float):
            return self._markup_int(entry)

        if isinstance(entry, bool):
            return self._markup_bool(entry)

        if isinstance(entry, NoneType):
            return self._markup_null(entry)

        return ''

